<?php require_once __DIR__ . '/../config/app.php'; require_admin(); ?>
<!DOCTYPE html><html lang="id"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Edit Denda</title><link rel="stylesheet" href="<?= h(app_url('asset/app.css')) ?>"></head><body><main class="form-page"><section class="form-card"><a class="back-link" href="<?= h(app_url('controllers/c_denda.php')) ?>">← Kembali ke denda</a><p class="eyebrow">ADMINISTRATOR</p><h1>Edit Denda #<?= (int)$data->id_denda ?></h1><form method="post" action="<?= h(app_url('controllers/c_denda.php?aksi=update')) ?>" class="stack"><input type="hidden" name="id_denda" value="<?= (int)$data->id_denda ?>"><label>Jenis Denda<select name="jenis_denda" id="jenis-denda" required><?php foreach (['Terlambat Mengembalikan Buku','Kerusakan','Hilang'] as $type): ?><option value="<?= h($type) ?>" <?= $data->jenis_denda === $type ? 'selected' : '' ?>><?= h($type) ?></option><?php endforeach; ?></select></label><label>Jumlah Hari Keterlambatan<input type="number" name="jumlah_hari_keterlambatan" id="hari" min="0" value="<?= (int)$data->jumlah_hari_keterlambatan ?>" required></label><label>Jumlah Denda (Rp)<input type="number" name="jumlah_denda" id="jumlah" min="0" step="1000" value="<?= h($data->jumlah_denda) ?>" required></label><label>Status Pembayaran<select name="status_denda" required><option value="Belum Dibayar" <?= $data->status_denda === 'Belum Dibayar' ? 'selected' : '' ?>>Belum Dibayar</option><option value="Sudah Dibayar" <?= $data->status_denda === 'Sudah Dibayar' ? 'selected' : '' ?>>Sudah Dibayar</option></select></label><button class="btn btn-primary" type="submit">Simpan Perubahan</button><?= csrf_field() ?></form></section></main><script>const type=document.getElementById('jenis-denda'),days=document.getElementById('hari'),amount=document.getElementById('jumlah');function calc(){if(type.value==='Terlambat Mengembalikan Buku'){amount.value=Math.max(0,Number(days.value))*<?= DENDA_PER_HARI ?>;amount.readOnly=true;}else{amount.readOnly=false;}}type.addEventListener('change',calc);days.addEventListener('input',calc);calc();</script></body></html>
